def task_func(goals, penalties, csv_file_path=CSV_FILE_PATH):
    total_goals = 0
    total_penalties = 0

    # Read existing counts from the CSV file if it exists
    if os.path.exists(csv_file_path):
        with open(csv_file_path, 'r', newline='', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                if 'goals' in row and row['goals'].strip():
                    total_goals += int(row['goals'])
                if 'penalties' in row and row['penalties'].strip():
                    total_penalties += int(row['penalties'])

    # Helper function to extract the total count whether the input is an int, dict, or list
    def get_total(x):
        if isinstance(x, dict):
            return sum(int(v) for v in x.values())
        elif isinstance(x, (list, tuple)):
            return sum(int(v) for v in x)
        elif x is None:
            return 0
        else:
            return int(x)

    # Update totals with the provided goals and penalties
    total_goals += get_total(goals)
    total_penalties += get_total(penalties)

    return Counter({'goals': total_goals, 'penalties': total_penalties})

import warnings
import os
import glob
import shutil
import time

def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    try:
        if not os.path.exists(DEST_DIR):
            os.makedirs(DEST_DIR, exist_ok=True)
    except Exception as e:
        warnings.warn(f"Unable to create destination directory: {e}")
        return transferred_files

    for ext in EXTENSIONS:
        # Handle extensions whether they start with a dot or not
        if ext.startswith('.'):
            pattern = f"*{ext}"
        else:
            pattern = f"*.{ext}"

        search_pattern = os.path.join(SOURCE_DIR, pattern)

        for file_path in glob.glob(search_pattern):
            file_name = os.path.basename(file_path)
            dest_path = os.path.join(DEST_DIR, file_name)

            try:
                shutil.move(file_path, dest_path)
                transferred_files.append(file_name)
            except Exception as e:
                warnings.warn(f"Unable to move file {file_name}: {e}")

    return transferred_files

