import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    This function evaluates file/directory names, rather than their full path. Predicates are deduplicated.

    Supported predicate formats:
      - "startswith:<text>"
      - "endswith:<text>"
      - "contains:<text>"
      - "regex:<pattern>"
      - "is_file"
      - "is_dir"
      - callable(name, path) -> bool
      - callable(name) -> bool

    Args:
        dir_path: Path to the directory whose immediate contents will be evaluated.
        predicates: List of predicate specifications.

    Returns:
        dict: A dictionary with directory items as keys and the results of condition checks as values.

    Raises:
        FileNotFoundError: If the specified directory does not exist or is not a directory.
        ValueError: If no valid predicates are provided.
    """
    # Validate directory path
    path = Path(dir_path)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"Directory does not exist or is not a directory: {dir_path}")

    # Ensure predicates is a list
    if not isinstance(predicates, list):
        predicates = [predicates]

    # Helper function to create predicate functions from specifications
    def _make_predicate(pred):
        # Handle callable predicates
        if callable(pred):
            try:
                label = pred.__name__
            except AttributeError:
                label = repr(pred)

            # Create wrapper that handles both callable(name) and callable(name, path)
            def _callable_wrapper(name, item_path, fn=pred):
                try:
                    return bool(fn(name, item_path))
                except TypeError:
                    # If TypeError, try calling with only 'name'
                    return bool(fn(name))

            return label, _callable_wrapper

        # Handle string predicates
        if not isinstance(pred, str):
            return None

        pred = pred.strip()
        if not pred:
            return None

        # Handle special predicates
        if pred == "is_file":
            return pred, lambda name, item_path: item_path.is_file()

        if pred == "is_dir":
            return pred, lambda name, item_path: item_path.is_dir()

        # Handle predicates with colon separator
        if ":" not in pred:
            return None

        kind, value = pred.split(":", 1)
        kind = kind.strip().lower()

        if kind == "startswith":
            return pred, lambda name, item_path, v=value: name.startswith(v)
        if kind == "endswith":
            return pred, lambda name, item_path, v=value: name.endswith(v)
        if kind == "contains":
            return pred, lambda name, item_path, v=value: v in name
        if kind == "regex":
            try:
                pattern = re.compile(value)
            except re.error:
                return None # Invalid regex pattern
            return pred, lambda name, item_path, p=pattern: bool(p.search(name))

        return None # Unrecognized string predicate format

    # Deduplicate predicates while preserving order
    seen = set()
    compiled_predicates = []

    for pred in predicates:
        # Create a key for deduplication
        # For simple types, use the value itself. For callables, use their ID.
        if isinstance(pred, (str, int, float, tuple)):
            key = pred
        else:
            key = id(pred)

        if key in seen:
            continue

        # Compile the predicate
        compiled = _make_predicate(pred)
        if compiled is not None:
            seen.add(key) # Add key to seen only if predicate was successfully compiled
            compiled_predicates.append(compiled)

    # Validate that we have at least one valid predicate
    if not compiled_predicates:
        raise ValueError("No valid predicates are provided.")

    # Evaluate each item in the directory
    results = {}
    for item in sorted(path.iterdir(), key=lambda p: p.name):
        item_results = {}
        for label, predicate_func in compiled_predicates:
            item_results[label] = predicate_func(item.name, item)
        results[item.name] = item_results

    return results

