    decoded_content = raw_content.decode(from_encoding)
    reencoded_content = decoded_content.encode(to_encoding)

    return json.loads(reencoded_content)

import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.setblocking(False)
    server_socket.bind((server_address, server_port))
    server_socket.listen(5)

    inputs = [server_socket]
    outputs = []
    message_queues = {}

    start_time = datetime.now()
    end_time = start_time + timedelta(seconds=run_duration)

    while inputs:
        current_time = datetime.now()
        timeout = (end_time - current_time).total_seconds()
        if timeout <= 0:
            break

        try:
            readable, writable, exceptional = select.select(inputs, outputs, inputs, timeout)
        except Exception:
            bad_sockets = []
            for s in inputs:
                try:
                    if s.fileno() == -1:
                        bad_sockets.append(s)
                except Exception:
                    bad_sockets.append(s)
            if not bad_sockets:
                break
            for s in bad_sockets:
                inputs.remove(s)
                if s in outputs:
                    outputs.remove(s)
                if s in message_queues:
                    del message_queues[s]
            continue

        for s in readable:
            if s is server_socket:
                try:
                    connection, client_address = s.accept()
                    connection.setblocking(False)
                    inputs.append(connection)
                    message_queues[connection] = queue.Queue()
                except Exception:
                    pass
            else:
                try:
                    data = s.recv(buffer_size)
                    if data:
                        current_time_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                        response = data + b" " + current_time_str.encode('utf-8')
                        message_queues[s].put(response)
                        if s not in outputs:
                            outputs.append(s)
                    else:
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        del message_queues[s]
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

        for s in writable:
            try:
                next_msg = message_queues[s].get_nowait()
            except queue.Empty:
                if s in outputs:
                    outputs.remove(s)
            except Exception:
                pass
            else:
                try:
                    s.send(next_msg)
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

        for s in exceptional:
            if s in inputs:
                inputs.remove(s)
            if s in outputs:
                outputs.remove(s)
            s.close()
            if s in message_queues:
                del message_queues[s]

    for s in inputs:
        try:
            s.close()
        except Exception:
            pass

    return f"Server ran for {run_duration} seconds."

import json
import requests
import os
from datetime import datetime

def task_func(json_data, unknown_key, save_dir=None):
    data = json.loads(json_data)
    url = data[unknown_key]

    response = requests.get(url)

    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"

    if save_dir is None:
        save_dir = os.getcwd()
    else:
        os.makedirs(save_dir, exist_ok=True)

    file_path = os.path.join(save_dir, filename)

    with open(file_path, 'wb') as f:
        if hasattr(response, 'content'):
            content = response.content
            if isinstance(content, str):
                content = content.encode('utf-8')
            f.write(content)
        elif hasattr(response, 'text'):
            f.write(response.text.encode('utf-8'))
        else:
            f.write(b'')

    return os.path.abspath(file_path)
